	if err != nil {
		return "", err
	}
	for {
		if info, e := os.Stat(filepath.Join(absolute, "pom.xml")); e == nil && !info.IsDir() {
			return absolute, nil
		}
		parent := filepath.Dir(absolute)
		if parent == absolute {
			return "", fmt.Errorf("project.root: no pom.xml found from %s", start)
		}
		absolute = parent
	}
